using System;using UnityEngine;using UnityEngine.InputSystem;using TMPro;
namespace CrossTheLine {
public sealed class CanaWedding:MonoBehaviour {
 public bool IsCinematic=>pouring>=0||drawing;public int FilledCount{get;private set;} public bool WineChanged{get;private set;}public int Stage{get;private set;}public Transform Player=>player;public Transform Cup=>cup;
 JourneyGame game;Transform player,servant,cup,stream;Material mat;Sprite square;GameObject environment;Transform[] jars=new Transform[6];Transform[] water=new Transform[6];bool[] filled=new bool[6];int pouring=-1;float timer;bool drawing,busy,instructed,shutdown,oldPixel;UnityEngine.Rendering.Universal.PixelPerfectCamera pixel;
 Color blue=new Color(.35f,.7f,.84f),wine=new Color(.55f,.12f,.26f);Vector3 target;
