 Color C(string h){ColorUtility.TryParseHtmlString("#"+h,out var c);return c;}
 Transform Shape(string name,Transform parent,Vector3 pos,Vector2 size,Color c,int order){var o=JourneyObjectFactory.Create(name);o.transform.SetParent(parent,false);o.transform.localPosition=pos;o.transform.localScale=new Vector3(size.x,size.y,1);var r=o.GetOrAddComponent<SpriteRenderer>();r.sprite=square;r.sharedMaterial=mat;r.color=c;r.sortingOrder=order;return o.transform;}
 Transform Shape(string n,float x,float y,float w,float h,string color,int order=0)=>Shape(n,environment.transform,new Vector3(x,y,0),new Vector2(w,h),C(color),order);
 Transform Actor(string name,Sprite sprite,float x,float y,float height=1.5f){var o=JourneyObjectFactory.Create(name);o.transform.SetParent(environment.transform,false);o.transform.position=JourneyStageLayout.Point(this,o.transform,"Placement 1",new Vector3(x,y,0));var body=JourneyObjectFactory.Create("Sprite");body.transform.SetParent(o.transform,false);var r=body.GetOrAddComponent<SpriteRenderer>();r.sprite=sprite;r.sharedMaterial=mat;r.sortingOrder=35+Mathf.RoundToInt(-y*4);float scale=height/sprite.bounds.size.y;body.transform.localScale=Vector3.one*scale;body.transform.localPosition=new Vector3(-sprite.bounds.center.x*scale,-sprite.bounds.min.y*scale,0);int i=Array.IndexOf(game.disciples,sprite);if(i>=0)body.GetOrAddComponent<DiscipleWalking>().Initialize(i,o.transform);return o.transform;}
 void Text(string text,float x,float y){var o=JourneyObjectFactory.Create(text);o.transform.SetParent(environment.transform,false);o.transform.position=JourneyStageLayout.Point(this,o.transform,"Placement 2",new Vector3(x,y,0));var t=o.GetOrAddComponent<TextMeshPro>();t.font=game.koreanFont;t.text=text;t.fontSize=2.6f;t.color=C("604536");t.alignment=TextAlignmentOptions.Center;t.GetComponent<RectTransform>().sizeDelta=new Vector2(8,1);t.GetComponent<MeshRenderer>().sortingOrder=70;}
 public void ConfigureStep(int step){JourneyObjectFactory.BeginStage(this,step);Stage=Mathf.Min(step,4);busy=false;instructed=false;pouring=-1;drawing=false;timer=0;FilledCount=Stage>=3?6:0;WineChanged=Stage>=4;Array.Clear(filled,0,6);if(environment)Destroy(environment);environment=JourneyObjectFactory.Create("CanaWeddingEnvironment");environment.transform.SetParent(transform,false);Shape("잔칫집 바닥",0,0,30,18,"dbc397",-10);Shape("뒤 벽",0,4,22,1.7f,"ecdab6",-8);Shape("천막 장식",0,3.3f,20,.25f,"953f43",-6);for(int i=0;i<12;i++)Shape("축하 장식",-8+i*1.5f,3.1f,.15f,.35f,i%2==0?"cead5e":"b56c63",-5);Shape("항아리 공간",-6.5f,-.5f,4.2f,6,"c4ad87",-7);Text("입구 · 돌항아리 여섯",-6.5f,2.8f);
 for(int i=0;i<6;i++){var o=JourneyObjectFactory.Create("돌항아리 "+(i+1));o.transform.SetParent(environment.transform,false);o.transform.position=JourneyStageLayout.Point(this,o.transform,"Placement 3",new Vector3(-7.6f+i%2*1.65f,1.3f-i/2*1.65f,0));jars[i]=o.transform;Shape("몸통",o.transform,new Vector3(0,0,0),new Vector2(.9f,1.05f),C("927b67"),12);Shape("항아리 어깨",o.transform,new Vector3(0,.35f,0),new Vector2(1.05f,.42f),C("aa9379"),13);Shape("목",o.transform,new Vector3(0,.63f,0),new Vector2(.63f,.22f),C("c5b08e"),14);Shape("입",o.transform,new Vector3(0,.73f,0),new Vector2(.68f,.10f),C("55463a"),15);water[i]=Shape("물 수위",o.transform,new Vector3(0,-.35f,0),new Vector2(.65f,.01f),blue,16);if(Stage>=3){filled[i]=true;water[i].localScale=new Vector3(.65f,.65f,1);water[i].localPosition=new Vector3(0,-.05f,0);}}
 for(int i=0;i<4;i++){float x=-2+i*3.25f;Shape("잔칫상",x,1.3f,2.4f,.65f,"8a5d3b",25);Shape("식탁보",x,1.48f,2.55f,.2f,"e8d8b4",26);Shape("음식 접시",x,1.64f,.7f,.12f,"c68c57",27);Actor("잔치 손님 "+i,game.supportingCast[5+i%2],x-.6f,1.8f,1.35f);Actor("잔치 손님 "+(i+4),game.supportingCast[i%2==0?2:6],x+.6f,1.8f,1.35f);}
 for(int i=0;i<3;i++){float x=-1+i*3.6f;Shape("가족 식탁",x,-3.9f,2.6f,.7f,"8a5d3b",27);Shape("식탁보",x,-3.6f,2.7f,.14f,"e8d8b4",28);Actor("잔치 손님 "+(i+8),game.supportingCast[6],x+.7f,-4.3f,1.3f);}
 Actor("베드로",game.disciples[0],.3f,-2.8f);Actor("안드레",game.disciples[1],2,-2.8f);Actor("빌립",game.disciples[4],3.6f,-2.8f);Actor("어머니 마리아",game.supportingCast[0],-1.8f,-2.6f);Actor("신랑",game.supportingCast[5],6.5f,-2.6f);Actor("잔치 주인",game.supportingCast[6],7.9f,-2.6f);servant=Actor("물을 채우는 종",game.supportingCast[5],-4,-1.4f);Actor("잔을 나르는 종",game.supportingCast[6],5.2f,-1.2f);
 cup=Shape("포도주가 되는 잔",-4.3f,.2f,.38f,.55f,"cfb68a",50);Shape("잔 속 음료",cup,Vector3.zero,new Vector2(.65f,.60f),WineChanged?wine:blue,51);cup.gameObject.SetActive(Stage>=3);stream=Shape("항아리에 붓는 물",-5,0,.08f,.8f,"73bbd9",60);stream.gameObject.SetActive(false);
 if(Stage==0){Shape("잔칫집 입구",0,-.1f,3,4,"9c744e",0);Shape("열린 문",0,-.35f,1.8f,3.3f,"675543",1);Text("가나 · 혼인잔치",0,3.2f);player.position=JourneyStageLayout.Point(this,player,"Placement 4",new Vector3(-3.8f,-3.6f,0));target=new Vector3(0,-1.7f,0);}else {player.position=JourneyStageLayout.Point(this,player,"Placement 5",new Vector3(-.8f,-1.3f,0));target=Stage==1?new Vector3(-1.8f,-2,0):Stage==2?new Vector3(-4,-1.3f,0):Stage==3?new Vector3(-4.5f,-1.3f,0):new Vector3(6.4f,-1.6f,0);}
 game.journeyCamera.orthographicSize=5.625f;UpdateCamera();game.BaptismCinema(false);Hud();}
 void Hud(){string[] labels={"입구로 들어가 혼인잔치에 참석하기","잔치를 즐기며 마리아와 이야기하기","종들에게 물을 채우게 하기 · "+FilledCount+" / 6","항아리에서 물을 떠 잔에 담기","연회장에게 포도주 전하기"};string prompt=Stage==2&&instructed?"항아리 옆으로 이동 · E로 종에게 물 채우기 지시":"WASD / 방향키 · 이동    가까이서 E · 이야기";game.WeddingHud(labels[Stage],prompt);}
 public void Tick(float dt,bool canMove,bool press){if(pouring>=0){var destination=jars[pouring].position+new Vector3(.85f,-.45f,0);if(Vector3.Distance(servant.position,destination)>.03f){servant.position=Vector3.MoveTowards(servant.position,destination,dt*4);stream.gameObject.SetActive(false);return;}stream.gameObject.SetActive(true);timer+=dt;float f=Mathf.Clamp01(timer/1.8f);water[pouring].localScale=new Vector3(.65f,.65f*f,1);water[pouring].localPosition=new Vector3(0,-.375f+.325f*f,0);stream.position=jars[pouring].position+new Vector3(.13f,1,0);if(timer>=1.8f){filled[pouring]=true;FilledCount++;pouring=-1;stream.gameObject.SetActive(false);game.BaptismCinema(false);Hud();if(FilledCount==6)game.BaptismAdvance();}return;}if(drawing){timer+=dt;cup.position=Vector3.Lerp(jars[0].position+new Vector3(.6f,.8f,0),new Vector3(-3.7f,-.1f,0),Mathf.Clamp01(timer/1.2f));if(timer>=1.3f){WineChanged=true;cup.GetChild(0).GetComponent<SpriteRenderer>().color=Color.Lerp(blue,wine,Mathf.Clamp01((timer-1.3f)/1.2f));}if(timer>=3.5f){drawing=false;game.BaptismCinema(false);game.BaptismAdvance();}return;}if(!canMove||busy)return;var k=Keyboard.current;Vector2 v=Vector2.zero;if(k!=null){v.x=(k.dKey.isPressed||k.rightArrowKey.isPressed?1:0)-(k.aKey.isPressed||k.leftArrowKey.isPressed?1:0);v.y=(k.wKey.isPressed||k.upArrowKey.isPressed?1:0)-(k.sKey.isPressed||k.downArrowKey.isPressed?1:0);}var p=player.position+(Vector3)(v.normalized*3.6f*dt);p.x=Mathf.Clamp(p.x,-8.7f,8.7f);p.y=Mathf.Clamp(p.y,-3.8f,.7f);player.position=p;game.MeetingWalk(v.sqrMagnitude>0,v.x);Hud();if(press)Interact();}
 public void Interact(){if(busy||IsCinematic)return;if(Stage==2&&instructed){for(int i=0;i<6;i++)if(!filled[i]&&Vector3.Distance(player.position,JarPosition(i))<1.4f){pouring=i;timer=0;stream.gameObject.SetActive(false);game.BaptismCinema(true);return;}return;}if(Vector3.Distance(player.position,target)>1.6f)return;busy=true;game.MeetingTalk(()=>{busy=false;if(Stage==2){instructed=true;Hud();}else if(Stage==3){drawing=true;timer=0;cup.gameObject.SetActive(true);game.BaptismCinema(true);}else game.BaptismAdvance();});}
 public void UpdateCamera(){game.journeyCamera.transform.position=JourneyStageLayout.Point(this,game.journeyCamera.transform,"Placement 6",new Vector3(0,0,-10));}
 public void Shutdown(){if(shutdown)return;shutdown=true;if(pixel)pixel.enabled=oldPixel;}
 void OnDestroy(){Shutdown();}
}
